     pub fn merge(mut self, other: impl Into<Router>) -> Self {
         let other = other.into();

+        // If the current router has a fallback, we need to preserve it.
+        // When merging, the other router's routes are added, but if the other router
+        // doesn't have a fallback, we should keep the current one.
+        // However, the flattening logic in `routes` might drop it if not handled correctly.
         self.routes.extend(other.routes);
         self.fallback = other.fallback.or(self.fallback);
         self
